#include <iostream>
#include <vector>

using namespace std;

/**
 * Variant 5: Using cin for input, cout for output, with static methods
 */

class NumberTheory {
public:
    class Mod998 {
    public:
        static const long long MOD = 998244353LL;

        static long long add(long long a, long long b) {
            long long res = a + b;
            if (res >= MOD) res -= MOD;
            return res;
        }

        static long long subtract(long long a, long long b) {
            long long res = a - b;
            if (res < 0) res += MOD;
            return res;
        }

        static long long mult(long long a, long long b) {
            return (a * b) % MOD;
        }

        static long long smallInv(long long a) {
            // Fermat's little theorem for modular inverse since MOD is prime
            return powMod(a, MOD - 2);
        }

        static long long powMod(long long base, long long exp) {
            long long result = 1;
            long long cur = base % MOD;
            while (exp > 0) {
                if (exp & 1) result = (result * cur) % MOD;
                cur = (cur * cur) % MOD;
                exp >>= 1;
            }
            return result;
        }

        static long long ncr(long long n, long long r) {
            if (r > n || r < 0) return 0;
            long long numerator = 1;
            long long denominator = 1;
            for (long long i = 1; i <= r; ++i) {
                numerator = mult(numerator, n - i + 1);
                denominator = mult(denominator, i);
            }
            return mult(numerator, smallInv(denominator));
        }
    };
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    using Mod = NumberTheory::Mod998;

    long long phaseSize = 1;
    long long p = 1;
    for (int i = 0; p != 0; ++i) {
        long long denom = Mod::smallInv(n + m - i);
        p = Mod::mult(p, n - i);
        p = Mod::mult(p, denom);
        phaseSize = Mod::add(phaseSize, p);
    }

    long long answer = 0;
    for (int k = 1; k <= n; ++k) {
        long long numPhases = Mod::mult(m + k, Mod::smallInv(k));
        long long term = Mod::mult(Mod::ncr(n, k), numPhases);
        term = Mod::mult(term, phaseSize);
        if (k & 1) {
            answer = Mod::add(answer, term);
        } else {
            answer = Mod::subtract(answer, term);
        }
    }

    cout << answer << "\n";

    return 0;
}

